import fs from 'node:fs/promises';
import { Presentation, PresentationFile } from '@oai/artifact-tool';
import {createRequire} from 'node:module';
const {FontLibrary}=createRequire(import.meta.resolve('@oai/artifact-tool'))('skia-canvas');
FontLibrary.use('Noto Sans CJK TC',[new URL('./NotoSansCJKtc-Regular.otf',import.meta.url).pathname]);
export const OUT=new URL('.',import.meta.url).pathname.replace(/\/$/,'');
export const COLORS={ink:'#111111',muted:'#555B65',rule:'#B8BCC4',panel:'#EDEDED',blue:'#3D8DFF',pale:'#D0EDFA'};
export const FONT='Noto Sans CJK TC';
export const presentation=Presentation.create({slideSize:{width:1280,height:720}});
export function text(slide,value,x,y,w,h,size=24,color=COLORS.ink,bold=false,name='text') {
  const s=slide.shapes.add({geometry:'textbox',name,position:{left:x,top:y,width:w,height:h},fill:'none',line:{fill:'none',width:0}});
  s.text=value;
  s.text.style={fontSize:size,typeface:FONT,color,bold,alignment:'left',verticalAlignment:'top',autoFit:'none',wrap:'none',insets:{top:0,right:0,bottom:0,left:0}};
  return s;
}
export function rule(slide,x,y,w){return slide.shapes.add({geometry:'line',position:{left:x,top:y,width:w,height:0},line:{fill:COLORS.rule,width:1}});}
export function base(title,num,subtitle='',note='') {
  const s=presentation.slides.add();s.background.fill='#FFFFFF';
  text(s,title,48,34,1184,72,48,COLORS.ink,false,'slide-title');
  if(subtitle)text(s,subtitle,48,119,1184,82,24,COLORS.muted,false,'slide-intro');
  text(s,'HIGHWAY SWAP SIM  /  模型驗證',48,673,950,26,22,COLORS.muted,false,'footer');
  text(s,String(num).padStart(2,'0'),1174,670,58,28,22,COLORS.muted,false,'page');
  if(note)s.speakerNotes.textFrame.setText(note);
  return s;
}
export function notes(slide,body,sources=[]){slide.speakerNotes.textFrame.setText(body+'\n\n[Sources]\n'+sources.join('\n')+'\n[/Sources]');}
export function table(slide,headers,rows,{left=48,top=236,width=1184,height=394,widths=null,size=24,aligns=[]}={}) {
 const vals=[headers,...rows];
 const t=slide.tables.add({rows:vals.length,columns:headers.length,left,top,width,height,values:vals,columnWidths:widths||Array(headers.length).fill(width/headers.length)});
 t.borders.assign({style:'solid',fill:COLORS.rule,width:1});
 t.cells.block({row:0,column:0,rowCount:vals.length,columnCount:headers.length}).assign({textStyle:{fontSize:size,typeface:FONT,color:COLORS.ink},margins:{left:12,right:12,top:5,bottom:5},anchor:'center'});
 for(let r=0;r<vals.length;r++){
  t.rows[r].height=height/vals.length;
  for(let c=0;c<headers.length;c++){
   const cell=t.getCell(r,c);cell.fill=r===0?COLORS.panel:'#FFFFFF';
   cell.text.style={fontSize:size,typeface:FONT,color:COLORS.ink,bold:r===0,alignment:aligns[c]||'left',verticalAlignment:'middle',autoFit:'none',wrap:'none'};
  }
 }
 return t;
}
export function pair(title,num,leftHead,leftBody,rightHead,rightBody,subtitle=''){
 const s=base(title,num,subtitle);
 text(s,leftHead,48,213,566,52,34,COLORS.ink,true,'left-heading');
 text(s,leftBody,48,280,566,326,28,COLORS.ink,false,'left-body');
 text(s,rightHead,664,213,568,52,34,COLORS.ink,true,'right-heading');
 text(s,rightBody,664,280,568,326,28,COLORS.ink,false,'right-body');
 return s;
}
export function chart(slide,categories,series,{left=48,top=212,width=600,height=408,yTitle='',numberFormat='0'}={}){
 return slide.charts.add('line',{position:{left,top,width,height},categories,series,hasLegend:true,legend:{position:'bottom',overlay:false,textStyle:{fontSize:22,fill:COLORS.ink}},lineOptions:{grouping:'standard',smooth:false},xAxis:{textStyle:{fontSize:22,fill:COLORS.ink},line:{fill:COLORS.rule,width:1}},yAxis:{title:{text:yTitle,textStyle:{fontSize:22,fill:COLORS.ink}},numberFormatCode:numberFormat,textStyle:{fontSize:22,fill:COLORS.ink},majorGridlines:{fill:COLORS.panel,width:1}},chartFill:'#FFFFFF',plotAreaFill:'#FFFFFF',chartLine:{fill:'none',width:0}});
}
export async function save(name='HighwaySwapSim_validation'){
 await fs.mkdir(OUT+'/renders',{recursive:true});
 for(const [i,s] of presentation.slides.items.entries()){
  const path=`${OUT}/renders/slide-${String(i+1).padStart(2,'0')}`;
  const p=await presentation.export({slide:s,format:'png',scale:1});await fs.writeFile(path+'.png',new Uint8Array(await p.arrayBuffer()));
  const l=await s.export({format:'layout'});await fs.writeFile(path+'.layout.json',await l.text());
 }
 const f=await PresentationFile.exportPptx(presentation);await f.save(`${OUT}/${name}.pptx`);
 await fs.writeFile(OUT+'/deck-inspection.ndjson',(await presentation.inspect({kind:'slide,textbox,table,chart,notes',maxChars:1000000})).ndjson);
 console.log(`${presentation.slides.items.length} slides: ${OUT}/${name}.pptx`);
}


